class Rectangulo:
    def __init__(self, base, altura):
        self.base = base
        self.altura = altura

    def describir(self):
        print(f'Rectángulo de {self.base}x{self.altura}')

    def calcular_area(self):
        return self.base * self.altura

r = Rectangulo(5, 3)
r.describir()
print(r.calcular_area())

solutionReferences.cpp:
#include <iostream>
class Rectangulo {
public:
    double base, altura;
    Rectangulo(double b, double h) : base(b), altura(h) {}
    void describir() const {
        std::cout << "Rectángulo de " << (int)base << "x" << (int)altura << "\n";
    }
    double calcularArea() const { return base * altura; }
};
int main() {
    Rectangulo r(5, 3);
    r.describir();
    std::cout << r.calcularArea() << "\n";
    return 0;
}
